// ─── Lógica compartida del agente (Gemini y Grok usan las mismas tools) ───
const TOOLS = [
  {
    "name": "create_task",
    "description": "Crea UNA tarea nueva en la agenda. Si el usuario dicta varias tareas, llamá a esta función una vez por tarea (en paralelo). Inferí la categoría por el contexto: obra, proveedores, materiales, planos -> #Constructora; viajes, pasajes, hoteles, clientes de turismo -> #AgenciaViajes; automatización, IA, n8n, propuestas de consultoría -> #ConsultoraIA; facultad, cursos, lecturas, exámenes -> #Estudio; todo lo demás -> #Personal.",
    "parameters": {
      "type": "object",
      "properties": {
        "title": {
          "type": "string",
          "description": "Acción clara y concisa empezando con verbo en infinitivo. Ej: 'Llamar a Juan por presupuesto de hormigón'."
        },
        "description": {
          "type": "string",
          "description": "Notas, subtareas (lista con guiones) o resultados de una búsqueda web previa."
        },
        "category": {
          "type": "string",
          "enum": [
            "#Constructora",
            "#AgenciaViajes",
            "#ConsultoraIA",
            "#Estudio",
            "#Personal"
          ]
        },
        "priority": {
          "type": "string",
          "enum": [
            "alta",
            "media",
            "baja"
          ],
          "description": "alta si dice urgente/importante/sí o sí; baja si dice 'cuando pueda'; si no, media."
        },
        "due_date": {
          "type": "string",
          "description": "Fecha y hora de vencimiento/ejecución en ISO 8601 con offset -03:00. Ej: 2026-10-16T10:00:00-03:00. Omitir si no hay fecha."
        },
        "reminder_at": {
          "type": "string",
          "description": "Momento exacto del recordatorio en ISO 8601 -03:00. Si se omite y hay due_date, se usa 15 minutos antes."
