const SYSTEM_TEMPLATE = "Sos el asistente ejecutivo personal de {{USER_NAME}}. Trabajás por voz y texto vía Telegram y gestionás su agenda de tareas.\n\n# Contexto temporal\n- Ahora es {{NOW_LOCAL}} ({{WEEKDAY}}), zona horaria America/Argentina/Buenos_Aires (UTC-3, sin horario de verano).\n- Resolvé siempre fechas relativas (\"mañana\", \"el jueves\", \"en dos horas\", \"a la tarde\") contra ese momento.\n- Convenciones: \"a la mañana\" = 09:00, \"al mediodía\" = 12:00, \"a la tarde\" = 16:00, \"a la noche\" = 20:00.\n- Toda fecha que envíes a una herramienta va en ISO 8601 con offset -03:00.\n\n# Áreas de trabajo (categorías)\n#Constructora · #AgenciaViajes · #ConsultoraIA · #Estudio · #Personal\n\n# Tareas abiertas (para coincidencia semántica)\nCuando el usuario diga \"ya hice X\", \"listo lo de X\", \"tachá X\", identificá la tarea en esta lista por significado (no por texto exacto) y usá su id. Si hay más de una candidata razonable, preguntá cuál antes de actuar.\n{{OPEN_TASKS}}\n\n# Reglas\n1. Actuá, no preguntes de más: si la intención es clara, ejecutá la herramienta directamente.\n2. Un audio puede contener varias instrucciones: ejecutá todas (podés llamar varias herramientas en paralelo).\n3. Títulos: verbo en infinitivo, concretos, sin la fecha adentro.\n4. \"Reprogramar en cadena\" / \"correr todo\" / \"me atrasé\" → reschedule_task con cascade=true.\n5. No tenés acceso a internet: si te piden investigar algo, creá una tarea para hacerlo.\n6. Nunca inventes ids. Si no está en la lista, usá find_tasks.\n\n# Respuesta final\n- Español rioplatense, breve, estilo mensaje de chat (máx. ~6 líneas salvo listados).\n- Confirmá qué hiciste con emojis sobrios: ✅ creada/completada, 📅 fecha, 🔁 reprogramada.\n- Mostrá fechas en formato humano: \"jue 16/10 10:00\".\n- Podés usar **negrita** para títulos de tareas. No uses tablas.\n";
const MAX_TURNS = 6;

/** Contexto: hora local, tareas abiertas e historial corto → system prompt. */
async function buildContext(chatId) {
  const ctx = await rpc('fn_agent_context', { p_chat_id: chatId });
  const openTasks = (ctx.open_tasks || [])
    .map((t) => `- id=${t.id} | ${t.title} | ${t.category} | ${t.priority} | ${t.status} | ${t.due_local || 'sin fecha'}`)
    .join('\n') || '(no hay tareas abiertas)';
  const systemText = SYSTEM_TEMPLATE
    .replace('{{USER_NAME}}', ENV.USER_NAME || 'el usuario')
    .replace('{{NOW_LOCAL}}', ctx.now_local)
    .replace('{{WEEKDAY}}', ctx.weekday)
    .replace('{{OPEN_TASKS}}', openTasks);
  return { systemText, history: ctx.history || [] };
}

const TOOL_HANDLERS = {
  create_task: (a) => rpc('fn_create_task', {
    p_title: a.title, p_description: a.description, p_category: a.category,
    p_priority: a.priority, p_due_date: a.due_date, p_reminder_at: a.reminder_at, p_source: 'telegram',
  }),
  list_tasks: (a) => rpc('fn_list_tasks', {
    p_range: a.range, p_from: a.from, p_to: a.to, p_category: a.category,
    p_statuses: a.include_completed ? ['pendiente', 'en_progreso', 'completada'] : undefined,
  }),
  find_tasks: (a) => rpc('fn_find_tasks', { p_query: a.query, p_limit: a.limit }),
  complete_task: (a) => rpc('fn_complete_task', { p_task_id: a.task_id, p_query: a.query, p_by: 'telegram' }),
  update_task: ({ task_id, ...patch }) => rpc('fn_update_task', { p_task_id: task_id, p_patch: patch, p_by: 'telegram' }),
  reschedule_task: (a) => rpc('fn_reschedule_task', {
    p_task_id: a.task_id, p_new_due: a.new_due_date, p_shift_minutes: a.shift_minutes,
    p_cascade: a.cascade === true ? true : undefined, p_by: 'telegram',
  }),
  cancel_task: (a) => rpc('fn_task_action', { p_task_id: a.task_id, p_action: 'cancel', p_by: 'telegram' }),
};

/** Ejecuta una tool y registra la acción. Los errores de la tool vuelven al modelo, no cortan el bucle. */
async function runTool(name, args, actions) {
  let result;
  try {
    if (!TOOL_HANDLERS[name]) throw new Error(`Herramienta desconocida: ${name}`);
    result = await TOOL_HANDLERS[name](args || {});
  } catch (e) {
    result = { status: 'error', message: e.message };
  }
  actions.push({ name, args: args || {}, status: result?.status, task_id: result?.task?.id || null });
  return result;
}

/** Guarda el intercambio en la memoria corta (agent_messages). */
async function logExchange(chatId, userText, reply, actions) {
  const note = actions.length
    ? `\n[acciones: ${actions.map((a) => `${a.name}${a.args.task_id ? '(' + a.args.task_id + ')' : a.args.title ? '(' + a.args.title + ')' : ''}`).join(', ')}]`
    : '';
  await rpc('fn_log_message', { p_chat_id: chatId, p_role: 'user', p_content: userText }).catch(() => {});
  await rpc('fn_log_message', { p_chat_id: chatId, p_role: 'model', p_content: reply + note }).catch(() => {});
}
// ─── fin agente compartido ───

// Agente PRINCIPAL: Gemini 2.5 Flash con audio nativo + Function Calling.
// Entrada: { kind: 'voice'|'text', chat_id, text?, audio_b64?, mime_type? }
// Si Gemini no responde (caído, 429, 5xx, timeout, bloqueo) se devuelve { fallback: true }
// y el workflow deriva a Grok (transcripción xAI + agente Grok).
const item = $input.first();
const input = item.json;
const chatId = input.chat_id;

// Prueba del respaldo a propósito:
//  - mensaje que empieza con "/grok ..."  → ese mensaje lo responde Grok
//  - variable FORZAR_GROK=true en n8n     → todo (incluidos audios) pasa por Grok
const porComando = input.kind === 'text' && /^\/grok\b/i.test(input.text || '');
if (porComando || String(ENV.FORZAR_GROK).toLowerCase() === 'true') {
  return [{
    json: {
      fallback: true,
      forced: true,
      error: porComando ? 'forzado con /grok' : 'forzado con FORZAR_GROK=true',
      kind: input.kind,
      chat_id: chatId,
      reply_to: input.message_id,
      text: porComando ? input.text.replace(/^\/grok\b\s*/i, '') || 'Decime qué tareas tengo hoy' : input.text,
      caption: input.caption,
      actions_done: [],
    },
    binary: item.binary,
  }];
}
const { systemText, history } = await buildContext(chatId);

const contents = history.map((m) => ({ role: m.role, parts: [{ text: m.content }] }));

// Audio nativo: el .ogg (Opus) de Telegram va como inlineData; Gemini lo escucha directo,
// sin transcripción intermedia (soporta audio/ogg; límite inline ~20 MB por request).
contents.push({
  role: 'user',
  parts: input.kind === 'voice'
    ? [
        { inlineData: { mimeType: input.mime_type || 'audio/ogg', data: input.audio_b64 } },
        { text: 'Nota de voz del usuario. Escuchala y ejecutá lo que pide.' + (input.caption ? ` Texto adjunto: ${input.caption}` : '') },
      ]
    : [{ text: input.text }],
});

let reply = '';
const actions = [];
try {
  for (let turn = 0; turn < MAX_TURNS; turn++) {
    const res = await geminiWithRetry({
      systemInstruction: { parts: [{ text: systemText }] },
      contents,
      tools: [{ functionDeclarations: TOOLS }],
      toolConfig: { functionCallingConfig: { mode: 'AUTO' } },
      generationConfig: { temperature: 0.3 },
    });

    const candidate = res?.candidates?.[0];
    if (!candidate?.content) {
      throw new Error(`Gemini sin respuesta (${res?.promptFeedback?.blockReason || candidate?.finishReason || 'vacía'})`);
    }
    const calls = (candidate.content.parts || []).filter((p) => p.functionCall);

    if (calls.length === 0) {
      reply = geminiText(res);
      break;
    }

    // Se reenvía el turno del modelo tal cual (conserva thought signatures de 2.5)
    contents.push(candidate.content);
    const responses = [];
    for (const { functionCall } of calls) {
      const result = await runTool(functionCall.name, functionCall.args, actions);
      responses.push({ functionResponse: { name: functionCall.name, response: { result } } });
    }
    contents.push({ role: 'user', parts: responses });
  }
} catch (e) {
  // → Respaldo con Grok. Se pasan las acciones ya ejecutadas para que no las repita.
  return [{
    json: {
      fallback: true,
      error: String(e.message || e).slice(0, 300),
      kind: input.kind,
      chat_id: chatId,
      reply_to: input.message_id,
      text: input.text,
      caption: input.caption,
      actions_done: actions,
    },
    binary: item.binary, // el audio viaja al nodo de transcripción de xAI
  }];
}

if (!reply) reply = actions.length ? '✅ Hecho.' : 'No pude procesar el pedido, ¿me lo repetís?';
await logExchange(chatId, input.kind === 'voice' ? '[nota de voz]' : input.text, reply, actions);

return [{ json: { fallback: false, provider: 'gemini', chat_id: chatId, reply_to: input.message_id, reply, actions } }];

